def terminate_owned(process, label):
    if process is None:
        return
    if process.poll() is None:
        log(f'STOP owned {label} pid={process.pid} pgid={process.pid}')
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        try:
            process.wait(timeout=45)
        except subprocess.TimeoutExpired:
            log(f'GRACEFUL TIMEOUT; SIGKILL owned process group {process.pid}')
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            process.wait(timeout=10)
    # Kill only a surviving member of the process group created by this supervisor.
    try:
        os.killpg(process.pid, 0)
    except ProcessLookupError:
        pass
    else:
        os.killpg(process.pid, signal.SIGTERM)
        time.sleep(1)
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
    log(f'EXIT {label} code={process.returncode}')
